import{_ as n,o as s,c as a,ah as t}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse(`{"title":"Décisions de fin d'année","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/decisions-fin-annee.md","filePath":"src/guide/admin/decisions-fin-annee.md"}`),i={name:"guide/admin/decisions-fin-annee.md"};function r(o,e,d,l,u,c){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="decisions-de-fin-d-annee" tabindex="-1">Décisions de fin d&#39;année <a class="header-anchor" href="#decisions-de-fin-d-annee" aria-label="Permalink to &quot;Décisions de fin d&#39;année&quot;">​</a></h1><p>À la fin de l&#39;année, chaque élève passe en classe supérieure, redouble ou quitte l&#39;établissement. ERA propose une décision pour chaque élève à partir de ses résultats ; <strong>l&#39;administrateur seul</strong> la valide ou la change. Ces décisions servent ensuite à <a href="/era-guide/guide/admin/reinscriptions.html">réinscrire les élèves</a> dans l&#39;année suivante.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><ul><li><strong>Les niveaux</strong> : chaque classe doit avoir un niveau, et chaque niveau son niveau suivant (voir <a href="/era-guide/guide/admin/structure-etablissement.html#niveaux">Niveaux</a>). Cochez <strong>Année d&#39;examen</strong> sur CM2, 3e et Terminale, et <strong>Dernier niveau de l&#39;établissement</strong> sur le plus haut.</li><li><strong>La moyenne de passage</strong> de chaque département : dans <strong>Paramétrage scolaire → Départements</strong>, champ <strong>Moyenne de passage</strong> (10 par défaut).</li><li><strong>La dernière période clôturée</strong> : les décisions s&#39;ouvrent une fois la dernière période de l&#39;année clôturée (voir <a href="/era-guide/guide/admin/structure-etablissement.html#cloturer-une-annee-ou-une-periode">Clôturer une année ou une période</a>). Les moyennes ne peuvent alors plus changer. Inutile d&#39;attendre la fin de l&#39;année : les conseils de classe de juin peuvent se tenir dès la clôture du dernier trimestre. Avant, la page montre déjà les propositions, en lecture seule.</li></ul><h2 id="decider-pour-une-classe" tabindex="-1">Décider pour une classe <a class="header-anchor" href="#decider-pour-une-classe" aria-label="Permalink to &quot;Décider pour une classe&quot;">​</a></h2><ol><li>Ouvrez <strong>Élèves et admissions → Décisions de fin d&#39;année</strong>.</li><li>Choisissez l&#39;<strong>Année scolaire</strong> puis la <strong>Classe</strong>. La liste des classes indique l&#39;avancement, par exemple « 12/35 décidés ».</li><li>Pour chaque élève, la page affiche sa <strong>Moyenne annuelle</strong> (en orange sous la moyenne de passage), la <strong>Proposition</strong> d&#39;ERA avec sa raison, et la <strong>Décision</strong> enregistrée.</li></ol><p>Trois façons d&#39;enregistrer les décisions :</p><ul><li><strong>Valider les propositions (n)</strong> : enregistre d&#39;un coup la proposition de tous les élèves de la classe qui n&#39;ont pas encore de décision. Les élèves déjà décidés ne sont jamais modifiés ; ceux sans proposition restent à décider un par un.</li><li><strong>Valider la proposition</strong>, sur la ligne d&#39;un élève.</li><li><strong>Décider</strong> (ou <strong>Modifier</strong>) : choisissez la décision vous-même et ajoutez si besoin une <strong>Observation</strong>, par exemple « Admis sur décision du conseil de classe ».</li></ul><p><strong>Annuler la décision</strong> remet l&#39;élève « à décider ».</p><p>Une fois l&#39;élève réinscrit dans l&#39;année suivante, sa décision ne peut plus être modifiée ni annulée : la ligne affiche « Réinscrit en … ».</p><p>Chaque décision garde la moyenne annuelle sur laquelle elle a été prise, son auteur et sa date.</p><h2 id="comment-era-propose" tabindex="-1">Comment ERA propose <a class="header-anchor" href="#comment-era-propose" aria-label="Permalink to &quot;Comment ERA propose&quot;">​</a></h2><p>Dans cet ordre :</p><table tabindex="0"><thead><tr><th>Situation</th><th>Proposition</th></tr></thead><tbody><tr><td>Exclusion définitive prononcée en conseil cette année</td><td>Quitte l&#39;établissement</td></tr><tr><td>Classe d&#39;un niveau marqué <strong>Année d&#39;examen</strong></td><td>Aucune : à décider selon les résultats d&#39;examen</td></tr><tr><td>Département évalué sans notes chiffrées (crèche, maternelle)</td><td>Admis</td></tr><tr><td>Aucune note cette année</td><td>Aucune : à décider</td></tr><tr><td>Moyenne annuelle au moins égale à la moyenne de passage</td><td>Admis</td></tr><tr><td>Moyenne annuelle sous la moyenne de passage</td><td>Redouble</td></tr></tbody></table><p>Une moyenne exactement égale à la moyenne de passage est une admission.</p><p>Sur le dernier niveau de l&#39;établissement, « Admis » s&#39;affiche <strong>Admis · fin de parcours</strong> : l&#39;élève a réussi et quitte l&#39;établissement.</p><div class="tip custom-block"><p class="custom-block-title">Une proposition n&#39;est qu&#39;un point de départ</p><p>Un élève à 9,50 peut être admis par le conseil de classe, un élève admis peut partir dans un autre établissement : changez simplement sa décision.</p></div>',17)])])}const g=n(i,[["render",r]]);export{m as __pageData,g as default};
